head.script:
scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        tabIndex : 2,
        editType : wf_sample.getObj("con_editType").getText(),
        initValue : "test value",
    }

    let cList = $c.gcm.createCList(properties)

    $c.gcm.createEmptyInput('tabIndex="1" initValue="start" style="width:200px; height:30px;"', '', 'startcomp');

    // comp 생성 함수 호출
    $c.gcm.createBasicSearchBox(cList, 'ev:onfocus="scwin.target1_onfocus"');

    // searchbox 는 내부 input 컴포넌트를 사용하므로 input.render 로 selectionStart/End 에 접근
    // wframe(common_P_editType_1.xml) 로드 후 onfocus 핸들러가 덮어써지므로 여기서 재정의
    scwin.target1_onfocus = function (e) {
        let rtn = '';

        rtn = target1.input.render.selectionStart;
        wf_sample.getObj("wf_body_bottom").getObj("scwin").setReturnValue("selectionStart : " + rtn);

        rtn = target1.input.render.selectionEnd;
        wf_sample.getObj("wf_body_bottom").getObj("scwin").setReturnValue("selectionEnd : " + rtn);
    }
}
